[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$CatalogPath,[string]$SchemaPath=(Join-Path $PSScriptRoot '..\references\resource-catalog.v1.schema.json'))
$ErrorActionPreference='Stop';$issues=@();if(-not(Test-Path -LiteralPath $CatalogPath -PathType Leaf)){throw "Catalog not found: $CatalogPath"};$catalog=Get-Content -LiteralPath $CatalogPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop;if(-not(Test-Path -LiteralPath $SchemaPath -PathType Leaf)){throw "Schema not found: $SchemaPath"};$null=Get-Content -LiteralPath $SchemaPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop
if($catalog.schemaVersion -ne 1){$issues+='schemaVersion must be 1'};if($catalog.catalogId -ne 'es-resource-reader.resource-catalog.v1'){$issues+='catalogId mismatch'};$items=@($catalog.items);$sources=@($catalog.sources);if($catalog.itemCount -ne $items.Count){$issues+='itemCount mismatch'};if($catalog.sourceCount -ne $sources.Count){$issues+='sourceCount mismatch'};$keys=@{};foreach($item in $items){$key=[string]$item.globalKey;if($keys.ContainsKey($key)){$issues+="duplicate globalKey: $key"};$keys[$key]=$true;if($key -ne (([string]$item.sourceId)+'|'+([string]$item.sourcePath))){$issues+="globalKey mismatch: $key"};if([string]$item.sourceSha256 -notmatch '^[a-f0-9]{64}$'){$issues+="invalid hash: $key"};if([string]$item.sourcePath -match '(^|[\\/])\.\.([\\/]|$)' -or [IO.Path]::IsPathRooted([string]$item.sourcePath)){$issues+="unsafe sourcePath: $key"};if([string]$item.status -notin @('ready','error')){$issues+="invalid status: $key"}}
[ordered]@{validator='Test-ESResourceReaderCatalog';catalogPath=(Resolve-Path $CatalogPath).Path;schemaPath=(Resolve-Path $SchemaPath).Path;valid=($issues.Count -eq 0);itemCount=$items.Count;sourceCount=$sources.Count;issues=$issues;runtimeStatus='runtime-not-run'}|ConvertTo-Json -Depth 8;if($issues.Count -gt 0){exit 1}
